+            DOC_TEMPLATE,
+            DateFormatter.forPattern(FormatNames.DATE_TIME.getName()).format(timestamp),
+            hostname,
+            pid,
+            method,
+            message,
+            InetAddresses.toAddrString(ipAddress),
+            memoryUsageBytes
+        );
+    }
