+        assertEquals(DequeUtils.dequeHashCode(dequeOne), DequeUtils.dequeHashCode(dequeTwo));
+    }
+
+    public void testNotEqualsAndHashCode() {
+        var dequeOne = DequeUtils.of(mock());
